def twos(bits):
    value = int(bits, 2)
    if bits[0] == "1":
        value -= 2 ** len(bits)       # the leftmost bit has a negative place value
    return value


def fp_to_denary(mantissa, exponent):
    m = twos(mantissa) / 2 ** (len(mantissa) - 1)   # binary point after the sign bit
    return m * 2 ** twos(exponent)


def is_normalised(mantissa):
    return mantissa[0] != mantissa[1]     # 01... positive, 10... negative


assert fp_to_denary("01101100", "0011") == 6.75
assert fp_to_denary("1011010000", "000101") == -19
assert fp_to_denary("10100000", "1101") == -0.09375
assert fp_to_denary("01111111", "0111") == 127       # largest in 8/4
assert fp_to_denary("10000000", "0111") == -128      # most negative in 8/4
assert not is_normalised("00010110")

